// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo, useState, type PointerEvent } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from multiLine ----
type MetroPoint = { date: Date; division: string; rate: number };

/** [division, baseline rate, recession sensitivity] */
const DIVISIONS: [string, number, number][] = [
  ['Bethesda-Gaithersburg-Frederick, MD', 2.6, 0.7],
  ['Nassau-Suffolk, NY', 3.6, 0.85],
  ['Boston-Cambridge-Quincy, MA', 3.9, 0.9],
  ['Seattle-Bellevue-Everett, WA', 4.3, 1.0],
  ['Camden, NJ', 4.4, 1.05],
  ['Newark-Union, NJ-PA', 4.7, 1.0],
  ['Los Angeles-Long Beach-Glendale, CA', 5.2, 1.25],
  ['Detroit-Livonia-Dearborn, MI', 6.4, 1.45]
];

const MONTHS = 168; // Jan 2000 through Dec 2013

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const bump = (month: number, center: number, width: number) =>
  Math.exp(-Math.pow((month - center) / width, 2));

const random = seededRandom(20260813);

/** Synthetic metro unemployment, shaped after the 2001 and 2008 recessions. */
const metroUnemployment: MetroPoint[] = DIVISIONS.flatMap(
  ([division, baseline, sensitivity]) => {
    let drift = 0;
    return Array.from({ length: MONTHS }, (_, month) => {
      // Carrying drift forward makes the noise correlated, so lines wander instead of jittering.
      drift = drift * 0.82 + (random() - 0.5) * 0.3;
      const cycle = 5.4 * bump(month, 121, 26) + 1.5 * bump(month, 38, 20);
      return {
        date: new Date(Date.UTC(2000, month, 1)),
        division,
        rate: Math.max(1.4, baseline + sensitivity * cycle + drift)
      };
    });
  }
);

const MARGIN = { top: 16, right: 20, bottom: 36, left: 44 };
const MUTED_STROKE = '#3d4145';

/** Long-form observations; rows sharing a `division` become one line. */
export type Data = { date: Date; division: string; rate: number }[];

export default function MultiLineChart({
  data = metroUnemployment,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [hovered, setHovered] = useState<number | null>(null);

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.rate) ?? 0])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const series = useMemo(() => {
    const line = d3
      .line<Data[number]>()
      .x((d) => x(d.date))
      .y((d) => y(d.rate));
    return Array.from(d3.group(data, (d) => d.division), ([division, values]) => ({
      division,
      path: line(values) ?? ''
    }));
  }, [data, x, y]);

  const color = useMemo(
    () => d3.scaleOrdinal(series.map((s) => s.division), d3.schemeObservable10),
    [series]
  );

  // Pixel-space copy of every point: hover does an exhaustive nearest search, which is fast enough.
  const points = useMemo(
    () =>
      data.map((d) => ({
        cx: x(d.date),
        cy: y(d.rate),
        division: d.division,
        rate: d.rate
      })),
    [data, x, y]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(Math.max(2, Math.round(innerWidth / 90))).map((v) => ({
      value: d3.utcFormat('%Y')(v),
      offset: x(v)
    })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  const focus = hovered === null ? null : points[hovered];

  // Drawing the focused series last is the JSX equivalent of the notebook's .raise().
  const ordered = focus
    ? [...series.filter((s) => s.division !== focus.division), ...series.filter((s) => s.division === focus.division)]
    : series;

  function handlePointerMove(event: PointerEvent<SVGSVGElement>) {
    const [mx, my] = d3.pointer(event, event.currentTarget);
    const nearest = d3.leastIndex(points, (p) =>
      Math.hypot(p.cx + MARGIN.left - mx, p.cy + MARGIN.top - my)
    );
    setHovered(nearest ?? null);
  }

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Multi-line chart of unemployment rate across eight US metro divisions, 2000 to 2013"
      style={{ touchAction: 'none' }}
      onPointerMove={handlePointerMove}
      onPointerLeave={() => setHovered(null)}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <text x={-MARGIN.left} y={-4} fill="var(--muted)" fontSize={11}>
          ↑ Unemployment (%)
        </text>
        {ordered.map((s) => (
          <path
            key={s.division}
            d={s.path}
            fill="none"
            stroke={!focus || focus.division === s.division ? color(s.division) : MUTED_STROKE}
            strokeWidth={focus?.division === s.division ? 2.2 : 1.5}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        ))}
        {focus && (
          <g transform={`translate(${focus.cx},${focus.cy})`} pointerEvents="none">
            <circle r={3} fill={color(focus.division)} />
            <text y={-10} textAnchor="middle" fill="var(--text)" fontSize={12}>
              {`${focus.division} · ${focus.rate.toFixed(1)}%`}
            </text>
          </g>
        )}
      </g>
    </svg>
  );
}
